responses.text:
{
  "checks": [
    {
      "title": "Hosts de confianza configurados en todas las cuentas de administrador",
      "clause_ref": {
        "chunk_id": "chunk-0001",
        "heading_path": ["Política de acceso administrativo al firewall perimetral"],
        "page": null,
        "quote": "Toda cuenta de administrador debe tener configurados hosts de confianza (trusted hosts) que restrinjan el origen de las sesiones de administración a las redes de gestión autorizadas."
      },
      "endpoints": ["admins"],
      "severity": "high",
      "intent": "Verificar que cada cuenta de administrador tenga al menos un trusted host configurado con una red específica (no 0.0.0.0/0).",
      "remediation": {
        "summary": "Configurar trusted hosts en cada cuenta de administrador para limitar el acceso a las redes de gestión autorizadas.",
        "steps": [
          "Ir a System > Administrators en la GUI de FortiGate.",
          "Editar cada cuenta de administrador.",
          "En el campo 'Trusted Hosts', ingresar las redes de gestión autorizadas (ej. 192.168.1.0/24).",
          "Guardar los cambios."
        ],
        "fortigate_cli": "config system admin\n    edit <admin_name>\n        set trusthost1 <red_de_gestion> <mascara>\n    next\nend"
      }
    },
    {
      "title": "Ninguna cuenta de administrador con trusted host 0.0.0.0/0",
      "clause_ref": {
        "chunk_id": "chunk-0001",
        "heading_path": ["Política de acceso administrativo al firewall perimetral"],
        "page": null,
        "quote": "No se permiten cuentas de administrador sin restricción de origen, es decir, con hosts de confianza equivalentes a 0.0.0.0/0."
      },
      "endpoints": ["admins"],
      "severity": "critical",
      "intent": "Verificar que ninguna cuenta de administrador tenga configurado 0.0.0.0/0 como trusted host, lo que permitiría acceso desde cualquier origen.",
      "remediation": {
        "summary": "Reemplazar el trusted host 0.0.0.0/0 en todas las cuentas de administrador por redes de gestión específicas.",
        "steps": [
          "Ir a System > Administrators en la GUI de FortiGate.",
          "Identificar las cuentas con trusted host 0.0.0.0/0.",
          "Editar cada cuenta afectada y reemplazar 0.0.0.0/0 por las redes de gestión autorizadas.",
          "Guardar los cambios."
        ],
        "fortigate_cli": "config system admin\n    edit <admin_name>\n        set trusthost1 <red_de_gestion> <mascara>\n    next\nend"
      }
    },
    {
      "title": "Bloqueo de cuenta tras máximo 3 intentos fallidos de autenticación",
      "clause_ref": {
        "chunk_id": "chunk-0001",
        "heading_path": ["Política de acceso administrativo al firewall perimetral"],
        "page": null,
        "quote": "Tras un máximo de tres (3) intentos fallidos consecutivos de autenticación, la cuenta de administrador debe bloquearse automáticamente."
      },
      "endpoints": ["system_global"],
      "severity": "high",
      "intent": "Verificar que el parámetro de intentos fallidos antes de bloqueo (admin-lockout-threshold) sea igual o menor a 3.",
      "remediation": {
        "summary": "Configurar el umbral de bloqueo de administrador a 3 intentos fallidos consecutivos.",
        "steps": [
          "Ir a System > Settings en la GUI de FortiGate.",
          "Buscar la sección de configuración de administración.",
          "Establecer 'Admin lockout threshold' en 3.",
          "Guardar los cambios."
        ],
        "fortigate_cli": "config system global\n    set admin-lockout-threshold 3\nend"
      }
    },
    {
      "title": "Duración del bloqueo por intentos fallidos no inferior a 300 segundos",
      "clause_ref": {
        "chunk_id": "chunk-0001",
        "heading_path": ["Política de acceso administrativo al firewall perimetral"],
        "page": null,
        "quote": "La duración del bloqueo por intentos fallidos no debe ser inferior a trescientos (300) segundos."
      },
      "endpoints": ["system_global"],
      "severity": "high",
      "intent": "Verificar que el parámetro de duración del bloqueo de administrador (admin-lockout-duration) sea igual o mayor a 300 segundos.",
      "remediation": {
        "summary": "Configurar la duración del bloqueo de administrador a un mínimo de 300 segundos.",
        "steps": [
          "Ir a System > Settings en la GUI de FortiGate.",
          "Buscar la sección de configuración de administración.",
          "Establecer 'Admin lockout duration' en 300 o más.",
          "Guardar los cambios."
        ],
        "fortigate_cli": "config system global\n    set admin-lockout-duration 300\nend"
      }
    },
    {
      "title": "Cierre automático de sesión por inactividad máximo 10 minutos",
      "clause_ref": {
        "chunk_id": "chunk-0001",
        "heading_path": ["Política de acceso administrativo al firewall perimetral"],
        "page": null,
        "quote": "Las sesiones administrativas deben cerrarse automáticamente tras un máximo de diez (10) minutos de inactividad."
      },
      "endpoints": ["system_global", "admins"],
      "severity": "medium",
      "intent": "Verificar que el tiempo de inactividad (admintimeout) global y por cuenta sea igual o menor a 10 minutos.",
      "remediation": {
        "summary": "Configurar el timeout de inactividad administrativo a un máximo de 10 minutos tanto a nivel global como en cada cuenta.",
        "steps": [
          "Ir a System > Settings en la GUI de FortiGate.",
          "Establecer 'Idle timeout' en 10 minutos o menos.",
          "Verificar también cuentas individuales por si tienen un timeout diferente configurado.",
          "Guardar los cambios."
        ],
        "fortigate_cli": "config system global\n    set admintimeout 10\nend"
      }
    },
    {
      "title": "Cierre de sesión por inactividad habilitado en todas las cuentas",
      "clause_ref": {
        "chunk_id": "chunk-0001",
        "heading_path": ["Política de acceso administrativo al firewall perimetral"],
        "page": null,
        "quote": "No se admite deshabilitar el cierre de sesión por inactividad en ninguna cuenta de administración."
      },
      "endpoints": ["admins", "system_global"],
      "severity": "medium",
      "intent": "Verificar que ninguna cuenta de administrador ni la configuración global tenga deshabilitado el cierre de sesión por inactividad.",
      "remediation": {
        "summary": "Asegurarse de que el timeout de inactividad esté habilitado (valor mayor a 0) en la configuración global y en todas las cuentas de administrador.",
        "steps": [
          "Ir a System > Settings en la GUI de FortiGate.",
          "Verificar que 'Idle timeout' tenga un valor mayor a 0 (no deshabilitado).",
          "Revisar cada cuenta de administrador para confirmar que no tengan el timeout deshabilitado.",
          "Guardar los cambios si es necesario."
        ],
        "fortigate_cli": "config system global\n    set admintimeout 10\nend"
      }
    },
    {
      "title": "Administración exclusivamente por HTTPS; HTTP deshabilitado en interfaces",
      "clause_ref": {
        "chunk_id": "chunk-0001",
        "heading_path": ["Política de acceso administrativo al firewall perimetral"],
        "page": null,
        "quote": "La administración del equipo debe realizarse exclusivamente mediante HTTPS; el acceso HTTP sin cifrar a la interfaz de administración debe estar deshabilitado o redirigido a HTTPS."
      },
      "endpoints": ["interfaces", "system_global"],
      "severity": "high",
      "intent": "Verificar que ninguna interfaz de administración tenga HTTP habilitado como protocolo de acceso administrativo.",
      "remediation": {
        "summary": "Deshabilitar HTTP en todas las interfaces de administración y asegurarse de que solo HTTPS esté habilitado.",
        "steps": [
          "Ir a System > Network > Interfaces en la GUI de FortiGate.",
          "Editar cada interfaz de administración.",
          "En 'Administrative Access', desmarcar 'HTTP' y asegurarse de que 'HTTPS' esté marcado.",
          "Guardar los cambios."
        ],
        "fortigate_cli": "config system interface\n    edit <interface_name>\n        unset allowaccess http\n        set allowaccess https\n    next\nend"
      }
    },
    {
      "title": "Telnet deshabilitado en todas las interfaces de red",
      "clause_ref": {
        "chunk_id": "chunk-0001",
        "heading_path": ["Política de acceso administrativo al firewall perimetral"],
        "page": null,
        "quote": "Ninguna interfaz de red debe permitir administración mediante HTTP ni Telnet."
      },
      "endpoints": ["interfaces"],
      "severity": "high",
      "intent": "Verificar que ninguna interfaz de red tenga Telnet habilitado como protocolo de acceso administrativo.",
      "remediation": {
        "summary": "Deshabilitar Telnet en todas las interfaces de red del FortiGate.",
        "steps": [
          "Ir a System > Network > Interfaces en la GUI de FortiGate.",
          "Editar cada interfaz.",
          "En 'Administrative Access', desmarcar 'Telnet'.",
          "Guardar los cambios."
        ],
        "fortigate_cli": "config system interface\n    edit <interface_name>\n        unset allowaccess telnet\n    next\nend"
      }
    }
  ]
}
